<script setup>
import { computed, reactive, ref } from 'vue';
import Avatar from '../components/Avatar.vue'; import Icon from '../components/Icon.vue'; import Modal from '../components/Modal.vue';
import { data, employees, byId, canEdit, config, token, presence, saveRecord, deleteRecord, notify } from '../store.js';
import { idEqual } from '../domain.js'; import { uploadPhoto } from '../services/api.js'; import { extractFace, loadImage, MODEL_ID } from '../services/recognition.js'; import { dateTime } from '../format.js';
const query = ref(''), department = ref(''), status = ref(''), editing = ref(false), form = reactive({}), error = ref(''), saving = ref(false), photoEmployee = ref(null), photoBusy = ref(false), photoStatus = ref(''), photoError = ref(''), photoInput = ref();
const rows = computed(() => employees.value.filter(e => `${e.fullName} ${e.personnelNumber}`.toLowerCase().includes(query.value.toLowerCase()) && (!department.value || idEqual(e.departmentId, department.value)) && (!status.value || e.status === status.value)));
const templates = computed(() => data.face_templates.filter(t => idEqual(t.employeeId, photoEmployee.value?.id)));
function edit(employee) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, employee ? { ...employee } : { fullName: '', personnelNumber: `EMP-${String(Math.max(0, ...data.employees.map(e => Number(e.personnelNumber?.replace(/\D/g, '')) || 0)) + 1).padStart(3, '0')}`, departmentId: data.departments[0]?.id || '', positionId: data.positions[0]?.id || '', accessLevelId: data.access_levels[0]?.id || '', status: 'active' }); error.value = ''; editing.value = true; }
async function submit() {
  saving.value = true; error.value = '';
  try {
    if (!form.fullName.trim() || !form.personnelNumber.trim()) throw new Error('Укажите ФИО и табельный номер.');
    if (data.employees.some(e => !idEqual(e.id, form.id) && e.personnelNumber.toLowerCase() === form.personnelNumber.trim().toLowerCase())) throw new Error('Табельный номер уже используется.');
    await saveRecord('employees', { ...form, fullName: form.fullName.trim(), personnelNumber: form.personnelNumber.trim() }); editing.value = false; notify('Сотрудник сохранён.');
  } catch (e) { error.value = e.message; } finally { saving.value = false; }
}
async function block(employee) { try { await saveRecord('employees', { id: employee.id, status: employee.status === 'active' ? 'blocked' : 'active' }); notify(employee.status === 'active' ? 'Доступ сотрудника заблокирован.' : 'Доступ сотрудника восстановлен.'); } catch (e) { notify(e.message, 'error'); } }
function openPhotos(person) { photoEmployee.value = person; photoError.value = ''; photoStatus.value = ''; }
async function addPhotos(event) {
  const files = [...(event.target.files || [])]; if (!files.length) return;
  photoBusy.value = true; photoError.value = ''; let added = 0;
  try {
    if (templates.value.length + files.length > 5) throw new Error('Для сотрудника можно сохранить до 5 фотографий.');
    for (const [index, file] of files.entries()) {
      photoStatus.value = `Фото ${index + 1} из ${files.length}: читаем изображение…`;
      const { canvas, blob } = await loadImage(file);
      const face = await extractFace(canvas, message => { photoStatus.value = `Фото ${index + 1}: ${message}`; });
      photoStatus.value = 'Сохраняем фотографию и признаки лица…';
      const photo = await uploadPhoto(config, token.value, blob);
      await saveRecord('face_templates', { employeeId: photoEmployee.value.id, embedding: face.embedding, modelId: MODEL_ID, ...photo, createdAt: new Date().toISOString() });
      added++;
      if (!photoEmployee.value.photoKey && !photoEmployee.value.photoUrl) {
        const saved = await saveRecord('employees', { id: photoEmployee.value.id, ...photo }); photoEmployee.value = saved;
      }
    }
    notify(`Добавлено фотографий: ${added}. Сотрудник готов к распознаванию.`);
  } catch (e) { photoError.value = `${added ? `Сохранено фото: ${added}. ` : ''}${e.message}`; }
  finally { photoBusy.value = false; photoStatus.value = ''; event.target.value = ''; }
}
async function removeTemplate(template) {
  if (!confirm('Удалить эту фотографию из набора распознавания?')) return;
  photoBusy.value = true; photoError.value = '';
  try {
    await deleteRecord('face_templates', template.id);
    if (photoEmployee.value.photoKey === template.photoKey && template.photoKey || photoEmployee.value.photoUrl === template.photoUrl && template.photoUrl) {
      const next = templates.value[0]; photoEmployee.value = await saveRecord('employees', { id: photoEmployee.value.id, photoKey: next?.photoKey || null, photoUrl: next?.photoUrl || null });
    }
    notify('Фото удалено из распознавания.');
  } catch (e) { photoError.value = e.message; } finally { photoBusy.value = false; }
}
</script>
<template><div class="page-header"><div><span class="eyebrow">УПРАВЛЕНИЕ ОРГАНИЗАЦИЕЙ</span><h1>Сотрудники<span class="heading-dot">.</span></h1><p>Карточки сотрудников, фотографии и назначенные уровни доступа.</p></div><button v-if="canEdit" class="button primary" @click="edit()"><Icon name="plus" :size="18" />Добавить сотрудника</button></div><div class="toolbar"><label class="search-field"><Icon name="search" :size="17" /><input v-model="query" placeholder="ФИО или табельный номер…" aria-label="Поиск сотрудника" /></label><select v-model="department" aria-label="Подразделение"><option value="">Все подразделения</option><option v-for="d in data.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select><select v-model="status" aria-label="Статус сотрудника"><option value="">Все статусы</option><option value="active">Активные</option><option value="blocked">Заблокированные</option></select><span class="toolbar-count">{{ rows.length }} сотрудников</span></div><section class="panel"><div v-if="!rows.length" class="empty-state"><Icon name="users" :size="36" /><h3>Сотрудники не найдены</h3><p>Измените фильтры или добавьте нового сотрудника.</p></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Подразделение / должность</th><th>Уровень доступа</th><th>Местоположение</th><th>Статус</th><th v-if="canEdit">Действия</th></tr></thead><tbody><tr v-for="person in rows" :key="person.id"><td><div class="person-cell"><Avatar :person="person" /><div><strong>{{ person.fullName }}</strong><small class="mono">{{ person.personnelNumber }}</small></div></div></td><td><strong class="cell-main">{{ byId('departments', person.departmentId)?.name || '—' }}</strong><small class="cell-sub">{{ byId('positions', person.positionId)?.name || '—' }}</small></td><td><span class="badge neutral"><Icon name="key" :size="13" />{{ byId('access_levels', person.accessLevelId)?.name || 'Не назначен' }}</span></td><td><span v-if="presence.has(String(person.id))" class="location-cell"><span class="dot"></span>{{ byId('rooms', presence.get(String(person.id)).roomId)?.name }}</span><span v-else class="muted">Неизвестно / вне помещений</span></td><td><span class="badge" :class="person.status === 'active' ? 'green' : 'red'">{{ person.status === 'active' ? 'Активен' : 'Заблокирован' }}</span></td><td v-if="canEdit"><div class="row-actions"><button class="icon-button" title="Фотографии и распознавание" :aria-label="`Фотографии: ${person.fullName}`" @click="openPhotos(person)"><Icon name="scan" :size="18" /></button><button class="icon-button" title="Изменить сотрудника" :aria-label="`Изменить: ${person.fullName}`" @click="edit(person)"><Icon name="edit" :size="17" /></button><button class="icon-button" :title="person.status === 'active' ? 'Заблокировать' : 'Разблокировать'" :aria-label="`${person.status === 'active' ? 'Заблокировать' : 'Разблокировать'}: ${person.fullName}`" @click="block(person)"><Icon :name="person.status === 'active' ? 'lock' : 'check'" :size="17" /></button></div></td></tr></tbody></table></div></section><Modal v-if="editing" :title="form.id ? 'Редактировать сотрудника' : 'Новый сотрудник'" @close="!saving && (editing = false)"><form id="employee-form" class="form-grid" @submit.prevent="submit"><label class="span-2">Фамилия и имя<input v-model="form.fullName" required maxlength="120" /></label><label>Табельный номер<input v-model="form.personnelNumber" required maxlength="30" /></label><label>Статус<select v-model="form.status"><option value="active">Активен</option><option value="blocked">Заблокирован</option></select></label><label>Подразделение<select v-model="form.departmentId" required><option value="" disabled>Выберите</option><option v-for="d in data.departments" :key="d.id" :value="d.id">{{ d.name }}</option></select></label><label>Должность<select v-model="form.positionId" required><option value="" disabled>Выберите</option><option v-for="p in data.positions" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="span-2">Уровень доступа<select v-model="form.accessLevelId"><option value="">Без уровня доступа</option><option v-for="a in data.access_levels" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><div v-if="error" class="alert-box span-2" role="alert">{{ error }}</div></form><template #footer><button class="button" :disabled="saving" @click="editing = false">Отмена</button><button class="button primary" form="employee-form" type="submit" :disabled="saving">{{ saving ? 'Сохраняем…' : 'Сохранить' }}</button></template></Modal><Modal v-if="photoEmployee" :title="`Фотографии · ${photoEmployee.fullName}`" wide @close="!photoBusy && (photoEmployee = null)"><div class="info-box"><Icon name="scan" /><p>Добавьте 3–5 чётких фото с небольшими поворотами головы. Для проверки используйте другой снимок. На каждой фотографии должен быть один человек.</p></div><input ref="photoInput" class="sr-only" type="file" accept="image/jpeg,image/png,image/webp" multiple @change="addPhotos" /><div class="face-gallery"><article v-for="template in templates" :key="template.id" class="face-thumb"><Avatar :person="{ ...photoEmployee, photoKey: template.photoKey, photoUrl: template.photoUrl }" size="photo" /><small>{{ dateTime(template.createdAt) }}</small><button class="icon-button danger" title="Удалить фото" :disabled="photoBusy" @click="removeTemplate(template)"><Icon name="trash" :size="16" /></button></article><button v-if="templates.length < 5" class="upload-tile" :disabled="photoBusy" @click="photoInput.click()"><Icon :name="photoBusy ? 'loader' : 'image'" :size="30" :class="{ spin: photoBusy }" /><strong>{{ photoBusy ? 'Обрабатываем…' : 'Добавить фото' }}</strong><span>JPG, PNG, WebP · до 12 МБ</span></button></div><p v-if="photoStatus" class="processing-status" role="status"><Icon name="loader" class="spin" :size="17" />{{ photoStatus }}</p><div v-if="photoError" class="alert-box" role="alert">{{ photoError }}</div><div class="subtle-note"><Icon name="help" :size="16" /><p>Распознавание выполняется на этом компьютере. Снимки и признаки сохраняются в выбранном хранилище.</p></div></Modal></template>
